     phase_record=data(f'sequence-{seq}/phase-81.bin');offset=141540 if label.endswith('before')else 145044;cpu_offset=36 if label.endswith('before')else 76;common_FX_offset=116 if label.endswith('before')else 628
     proof[label]=dict(prefix=prefix,full_State_equals_phase81=state==phase_record[offset:offset+3504],State_differing_offsets=[i for i in range(3504)if state[i]!=phase_record[offset+i]],whole_CPU_equals_phase81=cpu==list(struct.unpack_from('<10I',phase_record,cpu_offset)),checkpoint_runtime_FX_equals_Common_projected_FX=fx==phase_record[common_FX_offset:common_FX_offset+512],FX_differing_offsets=[i for i in range(512)if fx[i]!=phase_record[common_FX_offset+i]],full_State_constructed_from_FX=False,source_CPU=cpu,runtime_CPU=runtime,State_sha256=hashlib.sha256(state).hexdigest(),FX_sha256=hashlib.sha256(fx).hexdigest(),runtime_CPU_not_assumed_synchronized=True)
     keys.extend(prefix+'-'+suffix+'.bin'for suffix in('name','cpu','runtime-cpu','state','fx','page-2013458432','page-2013507584'))
